export default function TopicNotes({ subject, topicId, onProceed }) {
  const notes = ALL_NOTES[
    subject === 'english' && topicId === 'all'
      ? 'english_all'
      : subject === 'pyq' && topicId === 'all'
        ? 'pyq_all'
        : subject === 'current_affairs' && topicId === 'all'
          ? 'ca_all'
          : topicId
  ] || (subject === 'current_affairs' ? ALL_NOTES.ca_all : null);
  if (!notes) return null;
  const isEnglish = subject === 'english';

  return (
    <section className="topic-notes-page">
      <header className="topic-notes-header">
        <div>
          <span className="topic-notes-eyebrow">{isEnglish ? 'Study notes' : 'പഠനക്കുറിപ്പുകൾ'}</span>
          <h1>{notes.title}</h1>
          <p>{notes.intro}</p>
        </div>
      </header>

      <div className="topic-notes-start-actions">
        <button type="button" className="topic-notes-proceed" onClick={onProceed}>
          {isEnglish ? 'Continue to questions' : 'ചോദ്യങ്ങളിലേക്ക് പോകുക'}
        </button>
      </div>

      <div className="topic-notes-sections">
        {notes.sections.map((section, sectionIndex) => (
          <article className="topic-notes-section" key={section.title}>
            <h2>{section.title}</h2>
            <div className="topic-notes-items">
              {section.items.map(([label, detail]) => {
                const displayLabel = notes.title === 'Types of Sentences & Interchange'
                  ? (sectionIndex === 1
                    ? label.replace(/^(\d+)\.\s/, '7.$1 ')
                    : SENTENCE_NOTE_LABELS[label] || label)
                  : label;
                const isLineByLineLesson = subject === 'malayalam' || subject === 'current_affairs' || [
                  'Different Parts of Speech',
                  'Types of Sentences & Interchange',
                  'Subject-Verb Agreement (Concord)',
                  'Articles: A, An and The',
                  'Primary & Modal Auxiliary Verbs',
                  'Question Tags',
                  'Infinitives and Gerunds',
                  'Tenses',
                  'Tenses in Conditional Sentences',
                  'Prepositions',
                  'The Use of Correlatives',
                  'Direct and Indirect Speech',
                  'Active and Passive Voice',
                  'Correction of Sentences',
                  'Degrees of Comparison',
                  'Number, Gender & Collective Nouns',
                  'Word Formation, Prefixes & Suffixes',
                  'Compound Words',
                  'Synonyms',
                  'Antonyms',
                  'Phrasal Verbs',
                  'Foreign Words and Phrases',
                  'One Word Substitutes',
                  'Words Often Confused',
                  'Spelling Test',
                  'Idioms and their Meanings',
                  'General English — All Topics',
                  'Abbreviations and Expansions',
                  'മുൻവർഷ ചോദ്യങ്ങൾ — എല്ലാ വിഷയങ്ങളും',
                  'ഇന്ത്യൻ ഭരണഘടന (Constitution) — PYQ Notes',
                  'ഭൂമിശാസ്ത്രം (Geography) — PYQ Notes',
                  'ധനതത്വശാസ്ത്രം (Economics) — PYQ Notes',
                  'കേരളം ഭരണസംവിധാനങ്ങൾ (Kerala Governance) — PYQ Notes',
                  'ജനറൽ സയൻസ് (General Science) — PYQ Notes',
                  'കല, കായികം, സംസ്കാരം (Arts & Sports) — PYQ Notes',
                  'കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ (Computer Basics) — PYQ Notes',
                  'പ്രധാന നിയമങ്ങളും നിയമാവകാശങ്ങളും (Important Acts & Laws) — PYQ Notes',
                  'ആനുകാലിക സംഭവങ്ങൾ (Current Affairs) — PYQ Notes',
                  'ഗണിതവും മാനസികശേഷിയും (Maths & Mental Ability) — PYQ Notes',
                  'General English — PYQ Notes',
                  'മലയാളം (Malayalam Language) — PYQ Notes',
                  'ചരിത്രം (History) — PYQ Notes'
                ].includes(notes.title);
                const displayDetail = isLineByLineLesson
                  ? detail.replace(/(?=“)|(?=→)/g, '\n')
                  : detail;
                const isMainHeading = /^\d+\.\s/.test(displayLabel);
                return (
                  <div className={`topic-notes-item${isMainHeading ? ' topic-notes-item-major' : ''}`} key={label}>
                    <strong>{displayLabel}</strong>
                    <p className={isLineByLineLesson ? 'topic-notes-line-by-line' : undefined}>
                      {displayDetail}
                    </p>
                  </div>
                );
              })}
            </div>
          </article>
        ))}
      </div>

      <footer className="topic-notes-footer">
        <span>{isEnglish ? 'Finished reading? Continue to practice questions.' : 'കുറിപ്പുകൾ വായിച്ചുകഴിഞ്ഞോ? ഇനി ചോദ്യങ്ങൾ പരിശീലിക്കാം.'}</span>
        <button type="button" className="topic-notes-proceed" onClick={onProceed}>
          {isEnglish ? 'Continue to questions' : 'ചോദ്യങ്ങളിലേക്ക് പോകുക'}
        </button>
      </footer>
    </section>
  );
}
